const fmtARS = (n) => "$" + Math.round(n || 0).toLocaleString("es-AR");
const fmtARSshort = (n) => {
  if (!n) return "—";
  if (n >= 1_000_000) return "$" + (n/1_000_000).toFixed(2).replace(/\.?0+$/,'') + "M";
  if (n >= 1_000) return "$" + Math.round(n/1_000) + "k";
  return "$" + Math.round(n);
};
const fmtDate = (iso) => {
  if (!iso) return "—";
  const d = new Date(iso + "T12:00:00");
  return d.toLocaleDateString("es-AR", { day: "2-digit", month: "short" });
};
const daysUntil = (iso) => {
  if (!iso) return null;
  const now = new Date();
  const today = new Date(now.getFullYear(), now.getMonth(), now.getDate(), 12, 0, 0);
  const d = new Date(iso + "T12:00:00");
  return Math.round((d - today) / (1000*60*60*24));
};

/* Devuelve matriz local x servicio para un mes dado */
const buildMatrix = (mes) => {
  const rows = SERVICIOS_DATA.filter(r => r.mes === mes);
  const matrix = {};
  for (const local of LOCALES) {
    matrix[local] = {};
    for (const svc of SERVICIOS) matrix[local][svc] = null;
  }
  for (const r of rows) {
    if (!matrix[r.local]) matrix[r.local] = {};
    matrix[r.local][r.servicio] = r;
  }
  return matrix;
};

Object.assign(window, {
  LOCALES, SERVICIOS, FORMAS_PAGO, MESES, MES_ACTUAL,
  SERVICIOS_DATA, SERVICIO_CATEGORIA, CATEGORIA_COLOR,
  ESTADO_META,
  fmtARS, fmtARSshort, fmtDate, daysUntil, buildMatrix,
});
